import React, { useEffect, useState } from 'react';
import { Button, TextField, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper } from '@toi/tds';
import { listRecords } from '../api';
import { useToast, ToastProvider } from '@toi/tds';

const CustomerList: React.FC = () => {
  const [records, setRecords] = useState<any[]>([]);
  const [reason, setReason] = useState<string>('');
  const toast = useToast();

  useEffect(() => {
    const fetchRecords = async () => {
      try {
        const response = await listRecords(reason);
        setRecords(response.items);
      } catch (error) {
        toast.error('Failed to fetch records');
      }
    };

    fetchRecords();
  }, [reason]);

  return (
    <ToastProvider>
      <div>
        <TextField
          label="Query Reason"
          value={reason}
          onChange={(e) => setReason(e.target.value)}
          required
          minLength={5}
        />
        <Button onClick={() => setReason(reason)}>조회</Button>
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>ID</TableCell>
                <TableCell>Name</TableCell>
                <TableCell>Phone</TableCell>
                <TableCell>Status</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {records.map((record) => (
                <TableRow key={record.id}>
                  <TableCell>{record.id}</TableCell>
                  <TableCell>{record.name}</TableCell>
                  <TableCell>{record.phone}</TableCell>
                  <TableCell>{record.status}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </div>
    </ToastProvider>
  );
};

export default CustomerList;

import React from 'react';
import { createRoot } from 'react-dom/client';
import CustomerList from './CustomerList';

const App: React.FC = () => {
  return <CustomerList />;
};

createRoot(document.getElementById('root')!).render(<App />);

