import React, { useState } from 'react';
import { TextField, Button, ToastProvider, useToast } from '@toi/tds';
import { configureToiFetch, toiFetch } from '@toi/fetch';
import { listRecords, getRecord, updateStatus } from '../api';

const CustomerDetail = () => {
  const [id, setId] = useState('C001');
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [status, setStatus] = useState('active');
  const [reason, setReason] = useState('');
  const { showToast } = useToast();

  const handleGetRecord = async () => {
    try {
      const response = await getRecord(id, reason);
      setName(response.name);
      setPhone(response.phone);
      setStatus(response.status);
    } catch (error) {
      showToast({ message: 'Failed to get customer record', type: 'error' });
    }
  };

  const handleUpdateStatus = async () => {
    try {
      await updateStatus(id, status, reason);
      showToast({ message: 'Status updated successfully', type: 'success' });
    } catch (error) {
      showToast({ message: 'Failed to update status', type: 'error' });
    }
  };

  return (
    <ToastProvider>
      <div style={{ padding: '20px' }}>
        <TextField
          label='ID'
          value={id}
          onChange={(e) => setId(e.target.value)}
        />
        <TextField
          label='Name'
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <TextField
          label='Phone'
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
        />
        <TextField
          label='Status'
          value={status}
          onChange={(e) => setStatus(e.target.value)}
        />
        <TextField
          label='Reason'
          value={reason}
          onChange={(e) => setReason(e.target.value)}
          minLength={5}
        />
        <Button onClick={handleGetRecord}>조회</Button>
        <Button onClick={handleUpdateStatus}>상태 변경</Button>
      </div>
    </ToastProvider>
  );
};

export default CustomerDetail;

