import React, { useState } from 'react';
import { Button, TextField, Table, Badge, ToastProvider, useToast } from '@toi/tds';
import { configureToiFetch, toiFetch } from '@toi/fetch';
import { listRecords, getRecord, updateStatus } from '../api';

const OrderDetail = ({ orderId }) => {
  const [order, setOrder] = useState(null);
  const [reason, setReason] = useState('');
  const toast = useToast();

  const fetchOrder = async () => {
    try {
      const response = await toiFetch("orders", `/orders/${orderId}`, { reason });
      setOrder(await response.json());
    } catch (error) {
      toast.error('Failed to fetch order');
    }
  };

  const updateOrderStatus = async (newStatus) => {
    try {
      const response = await toiFetch("orders", `/orders/${orderId}`, {
        method: 'PATCH', reason, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: newStatus })
      });
      setOrder(await response.json());
      toast.success('Order status updated');
    } catch (error) {
      toast.error('Failed to update order status');
    }
  };

  React.useEffect(() => {
    fetchOrder();
  }, [orderId, reason]);

  return (
    <div>
      <h1>Order Detail</h1>
      <TextField
        label="Order ID"
        value={orderId}
        disabled
