import { createRoot } from 'react-dom/client';
import { Button, TextField, Table, Badge, ToastProvider, useToast } from '@toi/tds';
import { configureToiFetch, toiFetch } from '@toi/fetch';
// The trusted preview host injects runtime credentials; generated code never mints them.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

const { showToast } = useToast();

const RefundList = () => {
  const [reason, setReason] = React.useState('');
  const [refunds, setRefunds] = React.useState([]);

  const handleListRefunds = async () => {
    if (reason.length < 5) {
      showToast({
        title: 'Error',
        message: 'Reason must be at least 5 characters long.',
        type: 'error',
      });
      return;
    }
    try {
      const response = await toiFetch("refunds", '/refunds', { reason });
      setRefunds(response.items);
    } catch (error) {
      showToast({
        title: 'Error',
        message: 'Failed to fetch refunds.',
        type: 'error',
      });
    }
  };

  return (
    <div>
      <TextField
        label="Reason"
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        required
      />
      <Button onClick={handleListRefunds}>조회</Button>
      <Table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Order ID</th>
            <th>Amount</th>
            <th>Status</th>
            <th>Reason</th>
          </tr>
        </thead>
        <tbody>
          {refunds.map((refund) => (
            <tr key={refund.id}>
              <td>{refund.id}</td>
              <td>{refund.orderId}</td>
              <td>{refund.amount}</td>
              <td>{refund.status}</td>
              <td>{refund.reason}</td>
            </tr>
          ))}
        </tbody>
      </Table>
    </div>
  );};

export default function App() {
  return (
    <ToastProvider>
      <main>
        <h1>새 어드민</h1>
        <p>채팅으로 화면을 만들어 보세요.</p>
        <RefundList />
      </main>
    </ToastProvider>
  );}

