import React, { useState } from 'react';
import { TextField, Button, ToastProvider, useToast } from '@toi/tds';
import { configureToiFetch, toiFetch } from '@toi/fetch';
import { listRecords, getRecord, updateStatus } from '../api';

const RefundStatusChange = () => {
  const [id, setId] = useState('R001');
  const [amount, setAmount] = useState(0);
  const [status, setStatus] = useState('requested');
  const [reason, setReason] = useState('');
  const { showToast } = useToast();

  const handleGetRecord = async () => {
    try {
      const record = await getRecord(id, reason);
      setId(record.id);
      setAmount(record.amount);
      setStatus(record.status);
    } catch (error) {
      showToast({ message: 'Failed to get record', type: 'error' });
    }
  };

  const handleUpdateStatus = async () => {
    try {
      await updateStatus(id, status, reason);
      showToast({ message: 'Status updated successfully', type: 'success' });
    } catch (error) {
      showToast({ message: 'Failed to update status', type: 'error' });
    }
  };

  return (
    <div>
      <TextField
        label='ID'
        value={id}
        onChange={(e) => setId(e.target.value)}
      />
      <TextField
        label='Amount'
        value={amount}
        onChange={(e) => setAmount(Number(e.target.value))}
      />
      <TextField
        label='Status'
        value={status}
        onChange={(e) => setStatus(e.target.value)}
      />
      <TextField
        label='Reason'
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        minLength={5}
      />
      <Button onClick={handleGetRecord}>조회</Button>
      <Button onClick={handleUpdateStatus}>승인</Button>
    </div>
  );
};

export default RefundStatusChange;

