import React, { useEffect, useState } from 'react';
import { Button, TextField, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Badge, ToastProvider, useToast } from '@toi/tds';
import { listRecords, getRecord } from '../api';

const EmployeeList = () => {
  const [employees, setEmployees] = useState([]);
  const [reason, setReason] = useState('');
  const toast = useToast();

  useEffect(() => {
    const fetchEmployees = async () => {
      try {
        const response = await listRecords(reason);
        setEmployees(response.items);
      } catch (error) {
        toast.error('Failed to fetch employees');
      }
    };

    fetchEmployees();
  }, [reason]);

  const handleView = async (id) => {
    try {
      const response = await getRecord(id, reason);
      toast.success(`Viewed employee with ID: ${id}`);
      console.log(response);
    } catch (error) {
      toast.error('Failed to view employee');
    }
  };

  return (
    <div>
      <TextField
        label="Reason"
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        required
        minLength={5}
      />
      <Button onClick={() => setReason(reason)}>조회</Button>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>ID</TableCell>
              <TableCell>Name</TableCell>
              <TableCell>Department</TableCell>
              <TableCell>Phone</TableCell>
              <TableCell>Email</TableCell>
              <TableCell>RRN</TableCell>
              <TableCell>Account</TableCell>
              <TableCell>Status</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {employees.map((employee) => (
              <TableRow key={employee.id}>
                <TableCell>{employee.id}</TableCell>
                <TableCell>{employee.name}</TableCell>
                <TableCell>{employee.department}</TableCell>
                <TableCell>{employee.phone}</TableCell>
                <TableCell>{employee.email}</TableCell>
                <TableCell>{employee.rrn}</TableCell>
                <TableCell>{employee.account}</TableCell>
                <TableCell>
                  <Badge color={employee.status === 'active' ? 'success' : employee.status === 'inactive' ? 'error' : 'warning'}>{employee.status}</Badge>
                </TableCell>
                <TableCell>
                  <Button onClick={() => handleView(employee.id)}>View</Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </div>
  );
};

export default EmployeeList;

