import { createRoot } from 'react-dom/client';
import App from './App';
createRoot(document.getElementById('root')!).render(<App />);

import React, { useEffect, useState } from 'react';
import { Button, TextField, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper } from '@toi/tds';
import { listRecords, getRecord } from '../api';
import { useToast, ToastProvider } from '@toi/tds';

const CustomerOrderList: React.FC = () => {
  const [customers, setCustomers] = useState<any[]>([]);
  const [orders, setOrders] = useState<any[]>([]);
  const [reason, setReason] = useState<string>('');
  const toast = useToast();

  useEffect(() => {
    const fetchCustomers = async () => {
      try {
        const response = await listRecords(reason);
        setCustomers(response.items);
      } catch (error) {
        toast.error('Failed to fetch customers');
      }
    };

    const fetchOrders = async () => {
      try {
        const response = await listRecords(reason);
        setOrders(response.items);
      } catch (error) {
        toast.error('Failed to fetch orders');
      }
    };

    fetchCustomers();
    fetchOrders();
  }, [reason]);

  return (
    <ToastProvider>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        <TextField
          label='Reason'
          value={reason}
          onChange={(e) => setReason(e.target.value)}
          required
          minLength={5}
        />
        <Button onClick={() => setReason(reason)}>조회</Button>
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Customer ID</TableCell>
                <TableCell>Customer Name</TableCell>
                <TableCell>Phone</TableCell>
                <TableCell>Order ID</TableCell>
                <TableCell>Amount</TableCell>
                <TableCell>Status</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {customers.map((customer) => (
                <TableRow key={customer.id}>
                  <TableCell>{customer.id}</TableCell>
                  <TableCell>{customer.name}</TableCell>
                  <TableCell>{customer.phone}</TableCell>
                  {orders.map((order) => (
                    <TableRow key={order.id}>
                      <TableCell>{order.customerId}</TableCell>
                      <TableCell>{customer.name}</TableCell>
                      <TableCell>{customer.phone}</TableCell>
                      <TableCell>{order.id}</TableCell>
                      <TableCell>{order.amount}</TableCell>
                      <TableCell>{order.status}</TableCell>
                    </TableRow>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </div>
    </ToastProvider>
  );
};

export default CustomerOrderList;

