import React, { useEffect, useState } from 'react';
import { Button, TextField, Table, Badge, ToastProvider, useToast } from '@toi/tds';
import { listRecords, getRecord } from '../api';

const OrderList = () => {
  const [orders, setOrders] = useState([]);
  const [reason, setReason] = useState('');
  const toast = useToast();

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const response = await listRecords(reason);
        setOrders(response.items);
      } catch (error) {
        toast.error('Failed to fetch orders');
      }
    };

    fetchOrders();
  }, [reason]);

  const handleQuery = () => {
    if (reason.length < 5) {
      toast.error('Reason must be at least 5 characters long');
